\begin{aligned}
\mathrm{IsCoequalizer}_{\mathcal C}(Q,q,u,v)\Longleftrightarrow{}&
q\in\mathrm{Hom}_{\mathcal C}(A,Q)\land q\circ u=q\circ v\\
&\land\forall X\in\mathrm{Ob}(\mathcal C)\ \forall h\in\mathrm{Hom}_{\mathcal C}(A,X)\\
&\quad(h\circ u=h\circ v\Rightarrow\exists!w\in\mathrm{Hom}_{\mathcal C}(Q,X)\ (w\circ q=h)).
\end{aligned}
